const TITULO = 'Su ubicación';
const TEXTO = 'La constelación de Hidra se extiende desde el norte del ecuador celeste hasta los 35 grados al sur, por lo que todos los observadores pueden ver al menos una parte de ella. Hidra es la constelación más grande y también la más larga, abarcando 100 grados de este a oeste.';

const ANCHO = 6;
const ALTO = 3;
const SEPARACION = 0.9;

const boton = this;
let cartel;

function crearTextura() {
  const c = document.createElement('canvas');
  c.width = 1024; c.height = 512;
  const g = c.getContext('2d');

  g.fillStyle = 'rgba(10, 15, 45, 0.9)';
  g.beginPath();
  g.roundRect(0, 0, c.width, c.height, 40);
  g.fill();

  g.fillStyle = '#ffd27a';
  g.font = 'bold 64px sans-serif';
  g.fillText(TITULO, 50, 100);

  g.fillStyle = 'white';
  g.font = '40px sans-serif';
  let linea = '', y = 180;
  TEXTO.split(' ').forEach(p => {
    const prueba = linea + p + ' ';
    if (g.measureText(prueba).width > c.width - 100) {
      g.fillText(linea, 50, y);
      linea = p + ' ';
      y += 54;
    } else {
      linea = prueba;
    }
  });
  g.fillText(linea, 50, y);

  return new THREE.CanvasTexture(c);
}

function start() {
  boton.traverse(o => { if (o.material) o.material.side = THREE.DoubleSide; });
  const radio = boton.geometry && boton.geometry.parameters.radius || 1;

  cartel = new THREE.Mesh(
    new THREE.PlaneGeometry(ANCHO, ALTO),
    new THREE.MeshBasicMaterial({ map: crearTextura(), transparent: true, side: THREE.DoubleSide })
  );
  cartel.position.set(radio + SEPARACION + ANCHO / 2, 0, 0.01);
  cartel.visible = false;
  boton.add(cartel);

  // Cuando el cartel está oculto, que no se pueda tocar
  const raycastNormal = cartel.raycast.bind(cartel);
  cartel.raycast = (rc, resultados) => {
    if (cartel.visible) raycastNormal(rc, resultados);
  };

  // MindAR llama a esto SOLO cuando tocas este botón
  boton.onClick = () => {
    cartel.visible = !cartel.visible;
  };

  // MindAR llama a esto SOLO cuando tocas este cartel
  cartel.onClick = () => {
    cartel.visible = false;
  };
}

function stop() {
  if (cartel) boton.remove(cartel);
  delete boton.onClick;

}

