const NOMBRE_MODELO = 'CAMBIARRRR'; // nombre del objeto animado, tal como aparece en el panel Scene

const boton = this;
let mixer, accion;
let reproduciendo = false;

function start() {
  boton.traverse(o => { if (o.material) o.material.side = THREE.DoubleSide; });

  const modelo = scene.getObjectByName(NOMBRE_MODELO);
  if (!modelo || !modelo.animations || modelo.animations.length === 0) {
    console.warn('No encontré el modelo o no tiene animaciones:', NOMBRE_MODELO);
    return;
  }

  mixer = new THREE.AnimationMixer(modelo);
  accion = mixer.clipAction(modelo.animations[0]); // primera animación del modelo

  // MindAR llama a esto cuando tocas el botón
  boton.onClick = () => {
    if (!reproduciendo) {
      accion.paused = false;
      accion.play();
    } else {
      accion.paused = true;
    }
    reproduciendo = !reproduciendo;
  };
}

function update(event) {
  // event.delta viene en milisegundos y el mixer lo necesita en segundos
  if (mixer) mixer.update(event.delta / 1000);
}

function stop() {
  if (mixer) mixer.stopAllAction();
  delete boton.onClick;
}
